INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12324, 'Ts''epang Le Katse Ea Lehata', 'sesotho-(lesotho)', 'Tsepang  olula le batsoli ba hae empa o romeloa ke batsoali ba hae ho ea lula le Rangoane oa hae Teboho oa morui. Tseleng o qhekanyetysoa ke Katse ea lehata e ikentseng ngoanana. E mo kopa hore ba kalimisane ka mese le sefaha nako e khutsoane ha ba ntse ba tsamaisana tsela ho ea ha Rangoane Teboho. Ha ba fihl Katse e thetsa batho ba moo e re ke eona mochana oa Rangoane Teboho. Tsepang e be o lula naheng pela masimo a Rangoane oa hae a ntse a bina ho fihlela bafiti ka tsela ba mo utloa ebe ba bolella Rangoane oa hae. angoane oa hae o khutla le Tsepang e be ba etsetsa Katse leqheka ka ho mo chekela mokoti o nang le lebese. Katse e hloleha ke ho tlola mokoti e be e oela ka hare ebe Rangoane o e kupetsa ka mobu. Nível: First words. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/2158.png', NULL, 1898, 35, 30, 'asp-2158', 'cc-by', 0, NULL);
