INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12449, 'أنانسي و الحكمة', 'ar', 'في قديم الزمان، كان الناس لا يعرفون شيئا. كانوا لا يعرفون طريقة زراعة المحاصيل، أو نسج الأقمشة، أو صناعة الأدوات الحديدية. كان هناك الإله نيام في السماء وكان يملك كل الحكمة الموجودة في العالم. وكان محتفظا بها في وعاء من الفخار Nível: First paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/21824.png', NULL, 2141, 35, 30, 'asp-21824', 'cc-by', 0, NULL);
