INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12453, 'سمبقواير', 'ar', 'توفيت أم سمبقواير، فحزنت البنت حزنا شديدا. فعل أبوها كل ما في وسعه للعناية بها، فبدآ رويدا رويدا يسترجعان معا شعورهما بالفرح رغم غياب الأم. كانا يجلسان كل صباح ويتناقشان فيما سيفعلانه خلال اليوم. وفي المساء، كانا يحضران العشاء معا ويغسلان الأطباق ثم يقوم أب سمبقواير بمساعدتها في القيام بفروضها المنزلية Nível: Read aloud. Ilustração: Benjamin Mitchley.', 'http://africanstorybook.org/illustrations/covers/21835.png', NULL, 2142, 35, 30, 'asp-21835', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12454, 'Nilipata Funzo', 'sw', 'Msichana mdogo anadadisi anavyomtazama bibi akitayarisha kuzifukia ndizi ili ziwe mbivu. Nível: First words. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/21836.png', NULL, 2131, 35, 30, 'asp-21836', 'cc-by', 0, NULL);
