INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12459, 'Chicken And Millipede', 'en', 'Chicken and Millipede have a very competitive friendship. One day Chicken becomes so angry for losing that she does something very silly. Nível: First words. Ilustração: Magriet Brink.', 'http://africanstorybook.org/illustrations/covers/21843.png', NULL, 1472, 35, 30, 'asp-21843', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12460, 'خلاي تتحدث إلى النباتات', 'ar', 'خلاي تتحدث إلى النباتات. هذه خلاي عمرها سبع سنين معنى اسمها الشخص الجيد يدعا في لغتها لوبوكوزو Nível: First paragraphs. Ilustração: Jesse Pietersen.', 'http://africanstorybook.org/illustrations/covers/21846.png', NULL, 1976, 35, 30, 'asp-21846', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12461, 'زاما المميز!', 'ar', 'ينام أخي الصغير متأخرا جدا. أنا استيقظ باكرا لأنني مميزة! Nível: First sentences. Ilustração: Vusi Malindi.', 'http://africanstorybook.org/illustrations/covers/21847.png', NULL, 1976, 35, 30, 'asp-21847', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12462, 'البذرة الصغيرة – حكاية ونقاري ماتهاي', 'ar', 'في قرية على منحدر جبل كينيا بشرق إفريقيا، كان هناك فتاة صغيرة تدعى ونقاري تعمل مع أمها في الحقول Nível: First paragraphs. Ilustração: Maya Marshak.', 'http://africanstorybook.org/illustrations/covers/21848.png', NULL, 2142, 35, 30, 'asp-21848', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12463, 'لماذا لاتملك أفراس النهرشعرا', 'ar', 'لم تكن الفرس تعرف بوجود الأرنب فداست بطريق الخطأ على قدمه صرخ الأرنب بوجه فرس النهر،أنت يا فراس النهر! ألاترين أنك دست على قدمي ؟ Nível: First paragraphs. Ilustração: Carol Liddiment.', 'http://africanstorybook.org/illustrations/covers/21849.png', NULL, 1976, 35, 30, 'asp-21849', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12464, 'First Man and First Woman', 'en', 'A story about the beginning of the world and the first humans. They rise as snakes from the depths of a dark cold pool into a sunlit world of colour. As they move up to the surface the snakes change their form to start new lives. Nível: First paragraphs. Ilustração: Jemma Kahn.', 'http://africanstorybook.org/illustrations/covers/2185.png', NULL, 2140, 35, 30, 'asp-2185', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12465, 'جسدي', 'ar', 'لكنني لااستطيع به أن أطير. استطيع به أن أهرب Nível: First words. Ilustração: Mlungisi Dlamini.', 'http://africanstorybook.org/illustrations/covers/21850.png', NULL, 1976, 35, 30, 'asp-21850', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12466, 'الشعر', 'ar', 'زانيلي مشطت شعرها. ثيبو قص شعره. ثيمبا أزال شعره Nível: First words. Ilustração: Bronwen Heath.', 'http://africanstorybook.org/illustrations/covers/21851.png', NULL, 1976, 35, 30, 'asp-21851', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12467, 'الأخ الصغير الكسول', 'ar', 'أنا أغسل الصحون؟ لماذا أنا أعمل بجد. بينما أخي مشغول باللعب! Nível: First words. Ilustração: Mlungisi Dlamini.', 'http://africanstorybook.org/illustrations/covers/21852.png', NULL, 1976, 35, 30, 'asp-21852', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12468, 'الدجاجة والدودة', 'ar', 'كانت الدجاجة والدودة أصدقاء، لكنهم كانوا يتنافسون دائماً مع بعضهما البعض. في يوم من الأيام، قرروا لعب كرة القدم لمعرفة من هو أفضل لاعب Nível: First paragraphs. Ilustração: Magriet Brink.', 'http://africanstorybook.org/illustrations/covers/21853.png', NULL, 2141, 35, 30, 'asp-21853', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12469, 'الدجاجة والنسر', 'ar', 'عندما جاء النسر في اليوم التالي، وجد الدجاجة تبحث في الرمال، ولكن لا أثر للإبرة. فطار النسر إلى أسفل سريعا واختطف أحد أطفال الدجاجة وحمله بعيدا. بعد ذلك، كان كلما يظهر النسر، يجد الدجاجة تبحث في الرمال عن الإبرة Nível: First paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/21855.png', NULL, 2141, 35, 30, 'asp-21855', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12470, 'صغير الحمار', 'ar', 'كبر الحمار وأمه معاً ووجدا لنفسيهما سبلاً عديدة للتعايش في سلام جنباً إلى جنب. وشيئاً فشيئاً، بدأت عائلات أخرى تستقر حول الحمار وأمه Nível: First paragraphs. Ilustração: Meghan Judge.', 'http://africanstorybook.org/illustrations/covers/21856.png', NULL, 2142, 35, 30, 'asp-21856', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12471, 'تينغي و البقر', 'ar', 'واختبؤا بين الشجيرات حتى الليل. اخبئت الجدة تينغي تحت الأوراق Nível: First sentences. Ilustração: Ingrid Schechter.', 'http://africanstorybook.org/illustrations/covers/21857.png', NULL, 1976, 35, 30, 'asp-21857', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12472, 'كتاب الطقس', 'ar', 'كتاب الطقس. كتاب الطقس. كتاب الطقس.كتاب الطقس Nível: First words. Ilustração: Sandra McDougall.', 'http://africanstorybook.org/illustrations/covers/21858.png', NULL, 1976, 35, 30, 'asp-21858', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12473, 'أنديسوا نجمة كرة القدم', 'ar', 'شاهدت أنديسوا الصبية يلعبون كرة القدم كانت تتمنى لو أنها تستطيع أن تنضم إليهم فسألت المدرب إن كانت تستطيع أن تدرب Nível: First sentences. Ilustração: Eden Daniels.', 'http://africanstorybook.org/illustrations/covers/21859.png', NULL, 1976, 35, 30, 'asp-21859', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12474, 'في عطلة مع الجدة', 'ar', 'كان أودنقو وأبيو يعيشان مع أبيهما في المدينة، وكانا ينتظران العطلة بفارغ الصبر، ليس فقط لأن المدرسة ستغلق أبوابها ولكن أيضا لأنهما يريدان زيارة جدتهما التي كانت تعيش في قرية صيد محاذية لبحيرة كبيرة Nível: First paragraphs. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/21862.png', NULL, 2142, 35, 30, 'asp-21862', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12475, 'Kuhesabu Kabichi', 'sw', 'Hadithi ya hisabati kuhusu kuhesabu na kugawanya. (Hadithi hii iliwezeshwa na ufadhili wa Oppenheimer Memorial Trust). Nível: Longer paragraphs. Ilustração: Magriet Brink.', 'http://africanstorybook.org/illustrations/covers/21863.png', NULL, 1096, 35, 30, 'asp-21863', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12476, 'Korti el Ħämrä', 'egyptian-(latin)', 'Koorä ħämrä kbiira räyħä reħla. Translated by /kemet/. Nível: First words. Ilustração: Marion Drew.', 'http://africanstorybook.org/illustrations/covers/21864.png', NULL, 2143, 35, 30, 'asp-21864', 'cc-by', 0, NULL);
