INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12482, 'موز جدتي', 'ar', 'كانت لجدتي حديقة رائعة تملأها الذرة الرفيعة والدخن والكسافا، ولكن شجيرات الموز كانت أجمل ما في الحديقة. وكان لجدتي أحفادا كثيرين، إلا أنني كنت على يقين من أنني كنت المفضلة لديها. كانت تدعوني دوما إلى منزلها وكانت تودعني أسرارها الصغيرة، غير أن لجدتي سرا تخفيه عني ولا ترغب في اطلاعي عليه، ألا وهو المكان الذي تقوم فيه بإنضاج الموز Nível: Longer paragraphs. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/21873.png', NULL, 2142, 35, 30, 'asp-21873', 'cc-by', 0, NULL);
